import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  let [count, setCount] = useState(0);

  const increment = () => {
    count = count + 1;
  };

  const decrement = () => {
    count = count - 1;
  };

  return (
    <div>
      <h2 id="count">Count: {count}</h2>
      <button id="increment" onClick={increment}>Increment</button>
      <button id="decrement" onClick={decrement}>Decrement</button>
    </div>
  );
}

export default App;

