import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Frozen Counter', () => {
  test('Renders initial count of 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el) throw new Error('No #count element');
if (!el.textContent.includes('0')) throw new Error('Initial count should be 0');
  });

  test('Increment button updates count to 1', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#increment').click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('1')) throw new Error('Count should be 1 after clicking increment');
  });

  test('Decrement button decreases count', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#decrement').click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('0')) throw new Error('Count should be 0 after decrement');
  });
});
